#!/usr/bin/env node
// One fresh app, its DSH profile created from nothing, and `npm run dev`: the frame's rows must activate with no pending or failed entry.
//
//   node --import ./scripts/workspace-source.mjs scripts/verify-ide-profile.mjs
//
// The app is generated by the CLI's own profile generator (packages/cli/src/ide-profile.ts), installed from the registry plus this checkout's `ide/`
// packages (which must be built first: the gate's `pnpm run build` does that), and booted with a throwaway DSH home. Everything is removed afterwards.
import { spawn, spawnSync } from 'node:child_process'
import { cpSync, existsSync, mkdtempSync, readdirSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { applyIdeProfile, FRAME_PACKAGES } from '../packages/cli/src/ide-profile.ts'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const log = (message) => console.log(`verify-ide-profile: ${message}`)
const fail = (message) => {
  throw new Error(`verify-ide-profile: ${message}`)
}
const sleep = (ms) => new Promise((done) => setTimeout(done, ms))
async function until(fn, ms, every = 300) {
  const end = Date.now() + ms
  while (Date.now() < end) {
    const value = await fn().catch(() => undefined)
    if (value) return value
    await sleep(every)
  }
}

const DSH_VERSION = process.env.IDE_PROFILE_DSH_VERSION ?? '0.2.0-rc.2'
const FRAMEWORK_VERSION = process.env.IDE_PROFILE_FRAMEWORK_VERSION ?? '^1.0.10'

/**
 * The `ide/` packages as a published release would present them: every package in the closure of the frame's rows, as `file:` specs pointing at this
 * checkout, so `npm install` puts them (and their workspace dependencies, which npm does not resolve from `workspace:*`) into the app's node_modules.
 */
function frameSpecs() {
  const folders = new Map()
  for (const name of readdirSync(join(root, 'ide'))) {
    const folder = join(root, 'ide', name)
    const manifest = join(folder, 'package.json')
    if (!existsSync(manifest)) continue
    const parsed = JSON.parse(readFileSync(manifest, 'utf8'))
    if (!existsSync(join(folder, 'lib')))
      fail(`${parsed.name} is not built; run pnpm run build first`)
    folders.set(parsed.name, folder)
  }
  const closure = []
  const seen = new Set()
  const need = (name) => {
    if (seen.has(name) || !folders.has(name)) return
    seen.add(name)
    const parsed = JSON.parse(readFileSync(join(folders.get(name), 'package.json'), 'utf8'))
    for (const field of ['dependencies', 'peerDependencies'])
      for (const [dependency, range] of Object.entries(parsed[field] ?? {}))
        if (String(range).startsWith('workspace:')) need(dependency)
    closure.push(name)
  }
  for (const entry of FRAME_PACKAGES) if (entry.installed !== true) need(entry.name)
  return Object.fromEntries(closure.map((name) => [name, `file:${folders.get(name)}`]))
}

/** The framework packages the door's source imports (acryl-router, acryl-node-server, ...), as `file:` specs from this checkout's `plugins/`. */
function doorSpecsOf() {
  const folders = new Map()
  for (const name of readdirSync(join(root, 'plugins'))) {
    const folder = join(root, 'plugins', name)
    const manifest = join(folder, 'package.json')
    if (!existsSync(manifest)) continue
    folders.set(JSON.parse(readFileSync(manifest, 'utf8')).name, folder)
  }
  const specs = {}
  const seen = new Set()
  const need = (name) => {
    if (seen.has(name) || !folders.has(name)) return
    seen.add(name)
    if (!existsSync(join(folders.get(name), 'lib')))
      fail(`${name} is not built; run pnpm run build first`)
    specs[name] = `file:${folders.get(name)}`
    const parsed = JSON.parse(readFileSync(join(folders.get(name), 'package.json'), 'utf8'))
    for (const field of ['dependencies', 'peerDependencies'])
      for (const [dependency, range] of Object.entries(parsed[field] ?? {}))
        if (String(range).startsWith('workspace:')) need(dependency)
  }
  for (const name of ['acryl-router', 'acryl-node-server']) need(name)
  return specs
}

const scratch = mkdtempSync(join(tmpdir(), 'ide-profile-boot-'))
let server
try {
  const home = join(scratch, 'home')
  // The app as a template ships it: the door as app source (its row mounts it), with the framework packages its source imports.
  const app = join(scratch, 'app')
  cpSync(join(root, 'plugins', 'acryl-door'), join(app, 'plugins', 'acryl-door'), {
    recursive: true,
    filter: (path) => !/node_modules|\/lib(\/|$)/u.test(path),
  })
  const doorSpecs = doorSpecsOf()
  const specs = { ...frameSpecs(), ...doorSpecs }
  const byRow = Object.fromEntries(
    FRAME_PACKAGES.filter((entry) => entry.spec !== '' || entry.installed !== true).map((entry) => [
      entry.row ?? entry.name,
      entry.name,
    ]),
  )
  const input = {
    appName: 'boot',
    dshVersion: DSH_VERSION,
    frameworkVersion: FRAMEWORK_VERSION,
    spec: (row) => (byRow[row] === undefined ? undefined : specs[byRow[row]]),
    dependencies: specs,
  }
  const wrote = applyIdeProfile(app, input)
  if (!wrote.written.includes('cordis.patch.yml'))
    fail(`the generator did not write the overlay: ${JSON.stringify(wrote)}`)
  const again = applyIdeProfile(app, input)
  if (again.written.length > 0)
    fail(`generation is not idempotent: rewrote ${again.written.join(', ')}`)
  log('a fresh app is generated, and generating it again changes nothing')

  const install = spawnSync('npm', ['install', '--no-audit', '--no-fund'], {
    cwd: app,
    encoding: 'utf8',
    env: { ...process.env, npm_config_loglevel: 'error' },
  })
  if (install.status !== 0) fail(`npm install failed:\n${install.stdout}${install.stderr}`)
  log('installed the DSH pin, the framework and the frame packages')

  const env = { ...process.env, DSH_HOME: home, ACRYLBLENDS_HOME: join(scratch, 'app-home') }
  const prepared = spawnSync('npm', ['run', 'profile'], {
    cwd: app,
    env: { ...env, npm_config_loglevel: 'error' },
    encoding: 'utf8',
  })
  if (prepared.status !== 0)
    fail(`creating the profile failed:\n${prepared.stdout}${prepared.stderr}`)
  log("the profile is created from nothing by the app's own profile script")

  server = spawn('npm', ['run', 'dev'], { cwd: app, env, stdio: ['ignore', 'pipe', 'pipe'] })
  let output = ''
  server.stdout.on('data', (chunk) => (output += chunk))
  server.stderr.on('data', (chunk) => (output += chunk))
  const url = await until(
    async () => /(http:\/\/127\.0\.0\.1:\d+\/?\S*)/u.exec(output)?.[1],
    180_000,
  )
  if (!url) fail(`the app did not print a URL:\n${output}`)
  const profile = join(home, 'profiles', 'acrylblends-boot')
  if (!existsSync(profile))
    fail(`the app did not use its own profile: ${profile} is missing (log:\n${output})`)
  log(`the app boots on profile acrylblends-boot at ${url}`)

  let lastError = 'no answer'
  const jar = join(scratch, 'cookies.txt')
  const page = await until(async () => {
    const curl = spawnSync(
      'curl',
      ['-sL', '-b', jar, '-c', jar, '-o', join(scratch, 'page.html'), '-w', '%{http_code}', url],
      { encoding: 'utf8' },
    )
    const status = Number(curl.stdout)
    lastError = `HTTP ${String(status)}${curl.stderr ? ` ${curl.stderr}` : ''}`
    if (status > 0 && status < 400) return readFileSync(join(scratch, 'page.html'), 'utf8')
    return undefined
  }, 30_000)
  if (!page)
    fail(`the page did not answer at ${url} (${lastError}); server said:
${output.slice(-2000)}`)
  for (const gone of [/did not activate/u, /\bpending\b/u, /\bfailed\b/u])
    if (gone.test(output)) {
      const lines = output.split('\n')
      const around = lines.flatMap((line, index) =>
        gone.test(line) ? lines.slice(Math.max(0, index - 4), index + 5) : [],
      )
      fail(`a row did not activate:\n${[...new Set(around)].join('\n')}`)
    }
  const rows = FRAME_PACKAGES.map((entry) => entry.row ?? entry.name)
  log(`the frame's rows are in the overlay: ${rows.join(', ')}`)
  // Slice 2's workspace has a client half: its bundle must be in the page's module table, not only its host row active.
  if (!page.includes('acryl-workspace/client.js'))
    fail(`the page does not load the workspace client; server said:\n${output.slice(-2500)}`)
  log('the page loads the workspace client bundle')
  const tags = page.split('/api/acryl-door/page.js').length - 1
  if (tags !== 1)
    fail(
      `the page carries the door script ${String(tags)} times, expected once; server said:\n${output.slice(-2500)}`,
    )
  const door = spawnSync(join(app, '.acryl', 'bin', 'acryl'), ['brief', '--json'], {
    cwd: app,
    encoding: 'utf8',
  })
  if (door.status !== 0)
    fail(`a door call did not answer (exit ${String(door.status)}):\n${door.stdout}${door.stderr}`)
  log('the page carries the door script once, and a door call answers')
  log('every row activated, no pending or failed entry in the log')
  log('OK')
} finally {
  if (server) {
    server.kill('SIGTERM')
    await until(async () => (server.exitCode !== null ? true : undefined), 15_000)
    if (server.exitCode === null) server.kill('SIGKILL')
  }
  if (process.env.VERIFY_KEEP === '1') console.error(`verify-ide-profile: kept ${scratch}`)
  else rmSync(scratch, { recursive: true, force: true })
}
